// ============================================================================
// CONSTRUCTA - CÁLCULO DE MÉTRICAS EJECUTIVAS, ESTADO GENERAL Y PROMPT IA
// ============================================================================

const inputData = $input.first()?.json || {};
const now = new Date();
const nowIso = now.toISOString();
const fechaFormateada = now.toLocaleDateString('es-CR', {
  year: 'numeric', month: 'long', day: 'numeric'
});
const fechaCorta = now.toISOString().split('T')[0];

// Extracción segura de colecciones (con marcadores de 'Sin registros' o 'No disponible')
const projects = Array.isArray(inputData.projects) ? inputData.projects : [];
const expenses = Array.isArray(inputData.expenses) ? inputData.expenses : [];
const materials = Array.isArray(inputData.materials) ? inputData.materials : [];
const purchaseOrders = Array.isArray(inputData.purchaseOrders) ? inputData.purchaseOrders : [];
const requests = Array.isArray(inputData.requests) ? inputData.requests : [];
const materialRequests = Array.isArray(inputData.materialRequests) ? inputData.materialRequests : [];

// 1. CANTIDAD TOTAL DE PROYECTOS
const totalProjects = projects.length;

// 2. PROYECTOS ACTIVOS
const activeProjectsList = projects.filter(p => {
  const st = (p.estado || '').toLowerCase();
  const adv = Number(p.avance || p.progreso || 0);
  return !st.includes('finaliz') && !st.includes('terminad') && adv < 100;
});
const activeProjects = activeProjectsList.length;

// 3. PROYECTOS FINALIZADOS
const finishedProjects = projects.filter(p => {
  const st = (p.estado || '').toLowerCase();
  const adv = Number(p.avance || p.progreso || 0);
  return st.includes('finaliz') || st.includes('terminad') || adv >= 100;
}).length;

// 4. PROYECTOS ATRASADOS
const delayedProjectsList = activeProjectsList.filter(p => {
  const targetDateStr = p.fechaFinEstimada || p.fechaFin;
  if (!targetDateStr) return false;
  const targetDate = new Date(targetDateStr);
  return !isNaN(targetDate.getTime()) && now > targetDate;
});
const delayedProjects = delayedProjectsList.length;

// 5. AVANCE PROMEDIO
const avgProgress = totalProjects > 0
  ? Math.round(projects.reduce((acc, p) => acc + Number(p.avance || p.progreso || 0), 0) / totalProjects)
  : 0;

// PROYECTOS CON MENOR AVANCE Y MAYOR RIESGO
const sortedByProgress = [...activeProjectsList].sort((a, b) => Number(a.avance || 0) - Number(b.avance || 0));
const lowestProgressProject = sortedByProgress[0] ? `${sortedByProgress[0].nombre} (${sortedByProgress[0].avance || 0}%)` : 'Ninguno';
const highestRiskProject = delayedProjectsList[0] ? `${delayedProjectsList[0].nombre} (Plazo vencido)` : (sortedByProgress[0]?.nombre || 'Ninguno');

// 6. PRESUPUESTO TOTAL
const totalBudget = projects.reduce((acc, p) => acc + (Number(p.presupuesto) || 0), 0);

// 7. GASTO ACUMULADO
const totalSpent = expenses.reduce((acc, e) => acc + (Number(e.monto) || 0), 0);

// 8. PORCENTAJE DE EJECUCIÓN PRESUPUESTARIA
const budgetExecutionPct = totalBudget > 0 ? ((totalSpent / totalBudget) * 100).toFixed(1) : '0.0';
const totalDeviation = totalSpent - totalBudget;
const deviationFormatted = totalDeviation > 0 
  ? `+$${totalDeviation.toLocaleString()} MXN (Sobrecosto)` 
  : `-$${Math.abs(totalDeviation).toLocaleString()} MXN (Saldo a favor)`;

// 9. ÓRDENES DE COMPRA PENDIENTES Y ATRASADAS
const pendingPOsList = purchaseOrders.filter(po => {
  const st = (po.estado || '').toLowerCase();
  return !st.includes('recibid') || st.includes('parcial');
});
const pendingPurchaseOrders = pendingPOsList.length;

const delayedPOsList = pendingPOsList.filter(po => {
  const dStr = po.fechaPrometida || po.fechaSolicitada;
  if (!dStr) return false;
  const d = new Date(dStr);
  return !isNaN(d.getTime()) && now > d;
});
const delayedPurchaseOrders = delayedPOsList.length;

// 10. MATERIALES CRÍTICOS Y AGOTADOS
const outOfStockMaterialsList = materials.filter(m => Number(m.stockActual || 0) <= 0);
const criticalStockMaterialsList = materials.filter(m => {
  const stock = Number(m.stockActual || 0);
  const min = Number(m.stockMinimo || 0);
  return stock > 0 && stock <= min;
});
const criticalMaterials = criticalStockMaterialsList.length + outOfStockMaterialsList.length;
const outOfStockMaterialsCount = outOfStockMaterialsList.length;

// 11. SOLICITUDES PENDIENTES Y PRIORIDAD ALTA
const allRequests = [...requests, ...materialRequests];
const pendingRequestsList = allRequests.filter(r => {
  const st = (r.estado || '').toLowerCase();
  return st.includes('pend') || st.includes('revis') || st.includes('urgente');
});
const pendingRequests = pendingRequestsList.length;
const highPriorityRequests = pendingRequestsList.filter(r => {
  const prio = (r.prioridad || r.tipo || '').toLowerCase();
  return prio.includes('alta') || prio.includes('urgente');
}).length;

// 12 & 13. RIESGOS TOTALES Y CRÍTICOS
let totalRisks = 0;
let criticalRisks = 0;
let highRisks = 0;
let mediumRisks = 0;

// Riesgos por atraso en obras
if (delayedProjects > 0) {
  totalRisks += delayedProjects;
  criticalRisks += delayedProjects;
}

// Riesgos por sobrecosto presupuestario
for (const p of projects) {
  const b = Number(p.presupuesto) || 0;
  if (b > 0) {
    const spent = expenses.filter(e => String(e.proyectoId) === String(p.id)).reduce((s, e) => s + (Number(e.monto) || 0), 0);
    if (spent > b) {
      totalRisks++;
      const exc = ((spent - b) / b) * 100;
      if (exc >= 20) criticalRisks++;
      else if (exc >= 10) highRisks++;
      else mediumRisks++;
    }
  }
}

// Riesgos por insumos agotados o atraso de compras
if (outOfStockMaterialsCount > 0) {
  totalRisks += outOfStockMaterialsCount;
  criticalRisks += outOfStockMaterialsCount;
}
if (delayedPurchaseOrders > 0) {
  totalRisks += delayedPurchaseOrders;
  highRisks += delayedPurchaseOrders;
}

// DETERMINACIÓN DEL ESTADO GENERAL
let generalStatus = 'ESTABLE';
if (criticalRisks > 0 || delayedProjects > 0 || Number(budgetExecutionPct) > 120) {
  generalStatus = 'CRÍTICO';
} else if (highRisks > 0 || criticalMaterials > 0 || delayedPurchaseOrders > 0 || Number(budgetExecutionPct) > 105) {
  generalStatus = 'ATENCIÓN';
}

// RESUMEN DETERMINÍSTICO COMO BASE O FALLBACK
const deterministicSummary = `La cartera de CONSTRUCTA comprende ${totalProjects} obras con un avance físico promedio del ${avgProgress}%. ` +
  (delayedProjects > 0 
    ? `Se registran ${delayedProjects} proyecto(s) con fecha contractual vencida (${delayedProjectsList.map(p => p.nombre).join(', ')}). ` 
    : 'No se registran obras fuera de su fecha límite. ') +
  `El presupuesto autorizado suma $${totalBudget.toLocaleString()} MXN, con un gasto acumulado de $${totalSpent.toLocaleString()} MXN (${budgetExecutionPct}% de ejecución). ` +
  `En la cadena de suministros, se computan ${criticalMaterials} insumo(s) en umbral crítico y ${pendingPurchaseOrders} orden(es) de compra en curso (${delayedPurchaseOrders} con entrega retrasada).`;

// PROMPT EXCLUSIVO PARA IA (Sin alucinaciones)
const aiPrompt = `Analiza exclusivamente los datos proporcionados.\n` +
  `No inventes cifras.\n` +
  `No inventes proyectos.\n` +
  `No inventes riesgos.\n` +
  `No inventes fechas.\n` +
  `Resume la situación operativa de forma ejecutiva.\n` +
  `Identifica las situaciones que requieren atención.\n` +
  `Diferencia claramente entre datos y recomendaciones.\n\n` +
  `DATOS OPERATIVOS CERTIFICADOS DE CONSTRUCTA (${fechaCorta}):\n` +
  `- Total Proyectos: ${totalProjects} (Activos: ${activeProjects}, Finalizados: ${finishedProjects}, Atrasados: ${delayedProjects})\n` +
  `- Avance Promedio: ${avgProgress}%\n` +
  `- Presupuesto Global: $${totalBudget.toLocaleString()} MXN | Gasto Acumulado: $${totalSpent.toLocaleString()} MXN (${budgetExecutionPct}%)\n` +
  `- Desviación Financiera: ${deviationFormatted}\n` +
  `- Órdenes de Compra: ${pendingPurchaseOrders} pendientes (${delayedPurchaseOrders} retrasadas)\n` +
  `- Materiales Críticos: ${criticalMaterials} (Agotados: ${outOfStockMaterialsCount})\n` +
  `- Solicitudes: ${pendingRequests} pendientes (${highPriorityRequests} de alta prioridad)\n` +
  `- Riesgos Consolidados: ${totalRisks} (Críticos: ${criticalRisks}, Altos: ${highRisks}, Medios: ${mediumRisks})\n` +
  `- Estado General Computado: ${generalStatus}`;

return [{
  json: {
    fecha: fechaFormateada,
    fechaCorta,
    generalStatus,
    metrics: {
      totalProjects,
      activeProjects,
      finishedProjects,
      delayedProjects,
      avgProgress,
      lowestProgressProject,
      highestRiskProject,
      totalBudget: totalBudget.toLocaleString(),
      totalSpent: totalSpent.toLocaleString(),
      budgetExecutionPct,
      deviationFormatted,
      pendingPurchaseOrders,
      delayedPurchaseOrders,
      criticalMaterials,
      outOfStockMaterialsCount,
      pendingRequests,
      highPriorityRequests,
      totalRisks,
      criticalRisks,
      highRisks,
      mediumRisks
    },
    deterministicSummary,
    aiPrompt,
    recipient: $env.CONSTRUCTA_REPORT_EMAIL || 'admin@constructa.com'
  }
}];

