// ============================================================================
// CONSTRUCTA - ENSAMBLAJE FINAL DE REPORTE HTML EJECUTIVO
// ============================================================================

let prevNode = {};
try {
  prevNode = $('Calcular Métricas y Estado').first()?.json || {};
} catch (_) {}

const inputJson = $input.first()?.json || {};
const metricsNode = prevNode.metrics ? prevNode : (inputJson.metrics ? inputJson : {});

const m = metricsNode.metrics || {};
const fecha = metricsNode.fecha || new Date().toLocaleDateString('es-CR');
const fechaCorta = metricsNode.fechaCorta || new Date().toISOString().split('T')[0];
const estado = metricsNode.generalStatus || 'ESTABLE';
const recipient = metricsNode.recipient || $env.CONSTRUCTA_REPORT_EMAIL || 'admin@constructa.com';

// Selección de resumen: IA si tuvo éxito, o fallback determinístico
let resumenEjecutivo = metricsNode.deterministicSummary || '';
if (inputJson.ok && inputJson.text && inputJson.text.trim().length > 20) {
  resumenEjecutivo = inputJson.text.trim();
}

// Estilos del Estado General
const statusColors = {
  'CRÍTICO': { bg: '#dc2626', text: '#ffffff', border: '#b91c1c' },
  'ATENCIÓN': { bg: '#f59e0b', text: '#ffffff', border: '#d97706' },
  'ESTABLE': { bg: '#10b981', text: '#ffffff', border: '#059669' }
};
const statusStyle = statusColors[estado] || statusColors.ESTABLE;

// Recomendaciones ejecutivas automatizadas basadas en métricas
const acciones = [];
if (Number(m.delayedProjects || 0) > 0) {
  acciones.push(`Intervenir de forma prioritaria en ${m.delayedProjects} obra(s) con retraso para reprogramar cuadrillas y acordar addendas.`);
}
if (Number(m.delayedPurchaseOrders || 0) > 0) {
  acciones.push(`Exigir despacho a proveedores de las ${m.delayedPurchaseOrders} órdenes de compra retrasadas para no suspender frentes.`);
}
if (Number(m.criticalMaterials || 0) > 0) {
  acciones.push(`Gestionar órdenes de abastecimiento urgente para ${m.criticalMaterials} insumo(s) con stock por debajo del mínimo.`);
}
if (acciones.length === 0) {
  acciones.push('Mantener el plan de avance semanal conforme a los hitos programados.');
  acciones.push('Monitorear el ritmo de facturación y cobro de estimaciones de obra.');
  acciones.push('Continuar con las inspecciones de seguridad y control de calidad.');
}

