    <div style="padding:24px 32px; background:#ffffff; border-bottom:1px solid #e2e8f0;">
      <h3 style="margin:0 0 10px 0; font-size:14px; color:#475569; text-transform:uppercase; letter-spacing:0.5px;">RESUMEN EJECUTIVO</h3>
