        <h4 style="margin:0 0 10px 0; font-size:13px; color:#0f172a; text-transform:uppercase;">PROYECTOS</h4>
        <ul style="margin:0; padding-left:20px; font-size:13px; color:#334155; line-height:1.6;">
          <li><strong>Total:</strong> ${m.totalProjects ?? 0}</li>
          <li><strong>Activos:</strong> ${m.activeProjects ?? 0}</li>
          <li><strong>Finalizados:</strong> ${m.finishedProjects ?? 0}</li>
          <li><strong>Atrasados:</strong> <span style="color:${(m.delayedProjects || 0) > 0 ? '#dc2626' : '#16a34a'}; font-weight:700;">${m.delayedProjects ?? 0}</span></li>
        </ul>
      </div>

      <!-- AVANCE -->
      <div style="margin-bottom:20px; padding:16px 20px; background:#f8fafc; border-radius:8px; border:1px solid #e2e8f0;">
        <h4 style="margin:0 0 10px 0; font-size:13px; color:#0f172a; text-transform:uppercase;">AVANCE FÍSICO</h4>
        <ul style="margin:0; padding-left:20px; font-size:13px; color:#334155; line-height:1.6;">
          <li><strong>Promedio general:</strong> <strong>${m.avgProgress ?? 0}%</strong></li>
          <li><strong>Proyecto con menor avance:</strong> ${m.lowestProgressProject || 'N/A'}</li>
          <li><strong>Proyecto con mayor atención:</strong> ${m.highestRiskProject || 'N/A'}</li>
        </ul>
      </div>

      <!-- PRESUPUESTO -->
      <div style="margin-bottom:20px; padding:16px 20px; background:#f8fafc; border-radius:8px; border:1px solid #e2e8f0;">
        <h4 style="margin:0 0 10px 0; font-size:13px; color:#0f172a; text-transform:uppercase;">PRESUPUESTO Y FINANZAS</h4>
        <ul style="margin:0; padding-left:20px; font-size:13px; color:#334155; line-height:1.6;">
          <li><strong>Presupuesto autorizado:</strong> $${m.totalBudget || '0'} MXN</li>
          <li><strong>Gasto acumulado:</strong> $${m.totalSpent || '0'} MXN</li>
          <li><strong>Ejecución financiera:</strong> <strong>${m.budgetExecutionPct || '0'}%</strong></li>
          <li><strong>Desviación:</strong> ${m.deviationFormatted || 'Sin desviación'}</li>
        </ul>
      </div>

      <!-- COMPRAS -->
      <div style="margin-bottom:20px; padding:16px 20px; background:#f8fafc; border-radius:8px; border:1px solid #e2e8f0;">
        <h4 style="margin:0 0 10px 0; font-size:13px; color:#0f172a; text-transform:uppercase;">COMPRAS Y ABASTECIMIENTO</h4>
        <ul style="margin:0; padding-left:20px; font-size:13px; color:#334155; line-height:1.6;">
          <li><strong>Órdenes de compra pendientes:</strong> ${m.pendingPurchaseOrders ?? 0}</li>
          <li><strong>Órdenes con entrega retrasada:</strong> <span style="color:${(m.delayedPurchaseOrders || 0) > 0 ? '#ea580c' : '#16a34a'}; font-weight:700;">${m.delayedPurchaseOrders ?? 0}</span></li>
        </ul>
      </div>

      <!-- MATERIALES -->
      <div style="margin-bottom:20px; padding:16px 20px; background:#f8fafc; border-radius:8px; border:1px solid #e2e8f0;">
        <h4 style="margin:0 0 10px 0; font-size:13px; color:#0f172a; text-transform:uppercase;">INVENTARIO DE MATERIALES</h4>
        <ul style="margin:0; padding-left:20px; font-size:13px; color:#334155; line-height:1.6;">
          <li><strong>Materiales en stock crítico:</strong> ${m.criticalMaterials ?? 0}</li>
          <li><strong>Materiales agotados:</strong> <span style="color:${(m.outOfStockMaterialsCount || 0) > 0 ? '#dc2626' : '#16a34a'}; font-weight:700;">${m.outOfStockMaterialsCount ?? 0}</span></li>
        </ul>
      </div>

      <!-- SOLICITUDES -->
      <div style="margin-bottom:20px; padding:16px 20px; background:#f8fafc; border-radius:8px; border:1px solid #e2e8f0;">
        <h4 style="margin:0 0 10px 0; font-size:13px; color:#0f172a; text-transform:uppercase;">SOLICITUDES Y REQUERIMIENTOS</h4>
        <ul style="margin:0; padding-left:20px; font-size:13px; color:#334155; line-height:1.6;">
          <li><strong>Solicitudes pendientes:</strong> ${m.pendingRequests ?? 0}</li>
          <li><strong>Solicitudes de prioridad alta:</strong> ${m.highPriorityRequests ?? 0}</li>
        </ul>
      </div>

      <!-- RIESGOS -->
      <div style="margin-bottom:20px; padding:16px 20px; background:#f8fafc; border-radius:8px; border:1px solid #e2e8f0;">
        <h4 style="margin:0 0 10px 0; font-size:13px; color:#0f172a; text-transform:uppercase;">MATRIZ DE RIESGOS</h4>
        <ul style="margin:0; padding-left:20px; font-size:13px; color:#334155; line-height:1.6;">
          <li><strong>Riesgos Críticos:</strong> <span style="color:#dc2626; font-weight:700;">${m.criticalRisks ?? 0}</span></li>
          <li><strong>Riesgos Altos:</strong> <span style="color:#ea580c; font-weight:700;">${m.highRisks ?? 0}</span></li>
          <li><strong>Riesgos Medios:</strong> ${m.mediumRisks ?? 0}</li>
        </ul>
      </div>

      <!-- ACCIONES RECOMENDADAS -->
      <div style="padding:18px 20px; background:#f0fdf4; border-radius:8px; border-left:4px solid #16a34a;">
        <h4 style="margin:0 0 10px 0; font-size:13px; color:#14532d; text-transform:uppercase;">PRINCIPALES ACCIONES RECOMENDADAS</h4>
        <ol style="margin:0; padding-left:20px; font-size:13px; color:#166534; line-height:1.6;">
          ${acciones.map(a => `<li>${a}</li>`).join('')}
        </ol>
      </div>
    </div>

    <!-- PIE DE CORREO -->
    <div style="padding:20px 32px; background:#ffffff; border-top:1px solid #e2e8f0; font-size:12px; color:#64748b; text-align:center;">
      <p style="margin:0;">Este informe fue generado de forma automática por la plataforma de gestión CONSTRUCTA.</p>
      <p style="margin:4px 0 0 0; color:#94a3b8;">Para mayor detalle técnico, consulte el portal de administración.</p>
    </div>
  </div>
</body>
</html>
`.trim();

return [{
  json: {
    fecha,
    fechaCorta,
    estado,
    recipient,
    subject: `[CONSTRUCTA] Reporte ejecutivo diario — ${fechaCorta}`,
    htmlBody,
    metrics: m
  }
}];
